    add.s32 %r26, %r6, %r24;
    mad.lo.s32 %r27, %r26, 4, %r20;
    ld.shared.f32 %f6, [%r25];
    ld.shared.f32 %f7, [%r27];
    add.f32 %f6, %f6, %f7;
    st.shared.f32 [%r25], %f6;

    mad.lo.s32 %r28, %r6, 4, %r22;
    mad.lo.s32 %r29, %r26, 4, %r22;
    ld.shared.f32 %f8, [%r28];
    ld.shared.f32 %f9, [%r29];
    add.f32 %f8, %f8, %f9;
    st.shared.f32 [%r28], %f8;

