                y,
                weight,
                bias,
                running_mean,
                running_var,
                i32(N),
                i32(C),
                i32(H),
                i32(W),
                f32(self.eps),
                f32(self.momentum),
                i32(training_flag),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
